using json=nlohmann::json;
#include "../native/monitor_rtss_frame.h"
using namespace ymcc::monitorframe;using SdkApp=RTSS_SHARED_MEMORY::RTSS_SHARED_MEMORY_APP_ENTRY;
static_assert(offsetof(SdkApp,dwFrameTime)==offsetof(RtssAppPrefix,frameTimeUs));
int main(int argc,char**argv){if(argc!=2)return 2;json checks=json::array();auto check=[&](const char*n,bool ok){checks.push_back({{"name",n},{"ok",ok}});};const auto name=L"Local\\YMCC_RTSS_DUP_"+std::to_wstring(GetCurrentProcessId());const auto bytes=sizeof(RtssHeader)+sizeof(RtssAppPrefix);RtssHeader header{0x52545353,0x20015,sizeof(RtssAppPrefix),sizeof(RtssHeader),1,0,0,0,0,0};HANDLE map=CreateFileMappingW(INVALID_HANDLE_VALUE,nullptr,PAGE_READWRITE,0,(DWORD)bytes,name.c_str());assert(map);auto mem=(unsigned char*)MapViewOfFile(map,FILE_MAP_WRITE,0,0,bytes);assert(mem);memset(mem,0,bytes);memcpy(mem,&header,sizeof(header));auto app=(RtssAppPrefix*)(mem+header.appOffset);app->pid=GetCurrentProcessId();app->time0=10000;app->time1=11000;app->frames=120;app->frameBufferPos=1;app->frameTimeUs=8333;FILETIME c{},e{},k{},u{};assert(GetProcessTimes(GetCurrentProcess(),&c,&e,&k,&u));const auto birth=(uint64_t(c.dwHighDateTime)<<32)|c.dwLowDateTime;RtssReader reader(name.c_str());const auto tick=GetTickCount64();check("first read is warmup without current-frame proof",!reader.sample(GetCurrentProcessId(),birth,tick,1700000000000ULL).valid);app->time1=12000;app->frames=240;app->frameBufferPos=2;app->frameTimeUs=8123;const auto fresh=reader.sample(GetCurrentProcessId(),birth,tick+100,1700000000100ULL);check("advanced producer read is admitted",fresh.valid&&fresh.observedAt==1700000000100ULL);check("unchanged producer read is rejected before packet work",!reader.sample(GetCurrentProcessId(),birth,tick+200,1700000000200ULL).valid);UnmapViewOfFile(mem);CloseHandle(map);bool ok=true;for(auto&v:checks)ok=ok&&v["ok"].get<bool>();std::ofstream(argv[1])<<json({{"ok",ok},{"cases",checks},{"scope","Actual RTSS shared-memory adapter against a unique local fixture; no live RTSS or CPU measurement"}}).dump(2);return ok?0:1;}
